import zipfile, xml.etree.ElementTree as ET
path = r"D:\Download\File_template_BTL_2026.docx"
z = zipfile.ZipFile(path)
root = ET.fromstring(z.read("word/document.xml"))
attr = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val"
out = []
for par in root.iter():
    if par.tag.endswith("}p"):
        txt = "".join(t.text or "" for t in par.iter() if t.tag.endswith("}t")).strip()
        if txt:
            style = ""
            for child in par:
                if child.tag.endswith("}pPr"):
                    for c in child:
                        if c.tag.endswith("}pStyle"):
                            style = c.get(attr) or ""
                            break
                    break
            out.append((style, txt))
for s, t in out[:120]:
    print(s, t[:200])
print("TOTAL_PARAS", len(out))
